cat <<'EOF' > /tmp/discrepancyDetection.js
const disputedLines = ($vars.start.output.webhookPayload.dispute && $vars.start.output.webhookPayload.dispute.disputedLineItems) || [];
const erpRows = $vars.erpLookup1.output || [];

let totalOvercharge = 0;
let totalUndercharge = 0;
const lineResults = [];

disputedLines.forEach(function (disputed) {
  const erpRow = erpRows.find(function (row) { return Number(row.lineNumber) === Number(disputed.lineNumber); });
  if (!erpRow) {
    lineResults.push({
      lineNumber: disputed.lineNumber,
      description: disputed.description,
      disputedAmount: disputed.amount,
      contractedAmount: null,
      difference: null,
      matched: false
    });
    return;
  }
  const disputedAmount = Number(disputed.amount) || 0;
  const contractedAmount = Number(erpRow.amount) || 0;
  const difference = disputedAmount - contractedAmount;
  if (difference > 0) {
    totalOvercharge += difference;
  } else if (difference < 0) {
    totalUndercharge += Math.abs(difference);
  }
  lineResults.push({
    lineNumber: disputed.lineNumber,
    description: disputed.description,
    disputedQuantity: disputed.quantity,
    disputedUnitPrice: disputed.unitPrice,
    disputedAmount: disputedAmount,
    contractedQuantity: erpRow.quantity,
    contractedUnitPrice: erpRow.unitPrice,
    contractedAmount: contractedAmount,
    difference: difference,
    matched: true
  });
});

return {
  lineResults: lineResults,
  totalOvercharge: totalOvercharge,
  totalUndercharge: totalUndercharge,
  hasDiscrepancies: (totalOvercharge > 0 || totalUndercharge > 0)
};
